def transform(grid):
    h, w = len(grid), len(grid[0])
    line = next(c for c in range(w) if all(grid[r][c] == 5 for r in range(h)))
    out = [row[:] for row in grid]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(line):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            obj = []
            while stack:
                y, x = stack.pop()
                obj.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < line and grid[yy][xx] == 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objects.append(obj)
    for obj in objects:
        shift = line - 1 - max(x for y, x in obj)
        for y, x in obj:
            out[y][x] = 6
        for y, x in obj:
            out[y][x+shift] = 0
        ys = sorted(set(y for y, x in obj))
        candidates = []
        for y in ys:
            xs = sorted(x+shift for yy, x in obj if yy == y)
            # Rays come from a one-cell-thick pair of side walls.
            if len(xs) >= 2 and out[y][xs[0]+1] == 6 and out[y][xs[-1]-1] == 6:
                candidates.append(y)
        top, bottom = ys[0], ys[-1]
        topxs = sorted(x for y, x in obj if y == top)
        botxs = sorted(x for y, x in obj if y == bottom)
        closed = (topxs == list(range(topxs[0], topxs[-1]+1)) and
                  botxs == list(range(botxs[0], botxs[-1]+1)) and
                  topxs[0] == botxs[0] and topxs[-1] == botxs[-1])
        if closed:
            candidates = candidates[:2]
        for y in candidates:
            for xx in range(line+1, w):
                out[y][xx] = 2
    return out

